import { OrderRepository } from '../domain/OrderRepository';
import { OrderState } from '../domain/OrderState';
import { OrderDto } from './dto';
import { toOrderDto } from './DtoMapper';

export class ListOrdersUseCase {
  constructor(private readonly orders: OrderRepository) {}

  /** Lists every order, or only those in `state` when given. */
  execute(state?: OrderState): OrderDto[] {
    const orders = state ? this.orders.findByState(state) : this.orders.findAll();
    return orders.map(toOrderDto);
  }
}

